) AS (
  VALUES 
    (198::BIGINT, 'Un profesor que califica demasiado fuerte para lo que explica, pasa dando datos inutiles que no tienen que ver con la clase, poca práctica en clase, pide mucha participación, si a usted no le gusta que lo obliguen a participar no lo recomiendo, él piensa y espera que usted lo sepa todo ya.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-09-29T00:00:00+00:00'::TIMESTAMPTZ, '749679d0ccd35a522a77c0efa310b43d4a69a56d949e13b312061c7e24f091ce'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-09-24T00:00:00+00:00'::TIMESTAMPTZ, '15b2b425b155d5987fb772a67f8e37605f22a7f7b83d4638693ffe8e0ea5ce74'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es sabido que es un dolor de todo, ya fisica 2 es dificil y él no busca ayudarlo a pasar, habia otros profes que le rescata pts, él nunca va a hacer eso, porque tiene q estar bueno a la primera y sin rayones, la materia es muy pesada y es un ambiente feo de clase.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'cca21c5936699a96f2a74292ef7a4478364d811719dcd76823348bf09c8b9d27'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Es un buen profe, hay temas que los explica claros, otros que no. A mí si me ayudo bastante, pero se de otros alumnos que no el ayuda quien le caiga bien a la primera, aun así no es una mala opción personalmente. Quien lea esto sepan que algunos de los comentarios positivos los escribió él.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '044ed0a210d6872273208266f6b70bc2e3fe4b8f748bed202016a50279d49aa0'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es lo mejor de lo peor, póngale atención y entiende. Fácil se pierden puntos, por descuidos o no hacer las cosas como él, puede sacarse 0. Odia a la cátedra, y se complica bastante. No deje que le meta miedo, haga parciales viejos y pasa chill. TENGA CUIDADO EN LAB CON ÉL'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-12T00:00:00+00:00'::TIMESTAMPTZ, '1dc2974c0605565569a83444d22ee24bdb7c22469cf755c64c49d4d2dea22dd1'::TEXT, ARRAY[604, 607]::BIGINT[]),
    (198::BIGINT, 'El profe no sería tan molesto si no tuviera reglas tan sin sentido como usar solo hojas blancas, sin rayones ni marcas de lapiz borrado. Enseña bien, pero incumple mucho: llega MUY tarde o cancela la clase a 2 min de que empieze, si lo busca para consultas no aparece, etc...'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, '5fdcd2168fd752db30408d687f357678799d1d7895075434f66e74a00da654e8'::TEXT, ARRAY[604, 630, 607, 631]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-20T00:00:00+00:00'::TIMESTAMPTZ, '8a0d54cf224d17f7c2635bd0017374d83779fa53fe305671b9c2365e3ea1a45c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Como persona es muy bueno y muy comico y puede ser buena gente si usted muestra interes pero califica duro y en quices la mayoria de la clase los perdia porque por cualquier detalle daba el problema en 0 aparte en la exposicion buscaba cualquier cosa para bajar punto, en resumen en muy exigente'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'ff77aeabea15db8155e6a253c69b55dad320c218b5be9e1913630bee006a53a7'::TEXT, ARRAY[607]::BIGINT[]),
    (198::BIGINT, 'Explica demasiado bien todos los temas, pero califica demasiado duro. Hace quices sorpresa, es algo estricto con el formato de los trabajos a entregar, y suele hacer las clases muy dinámicas. En general, a uno lo prepara bastante bien para los exámenes de la cátedra pero califica muy duro.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'La participación importa']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'a60b21f89cc0f03bb4a241e5d77953d1062584d4f75e60489d3903c404331df3'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profe me parece excelente, explica muy bien la materia y hace ejemplos claros para que el estudiante entienda, claramente tiene que poner de su parte al estudiar en su casa. Además el profe hace la clase amena lo cual hace que entienda mejor.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ad7ba01a31fbc9c448df9a2d4251b934009db2c153c91b03b2d345f3dd21b69d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Cómo persona es bueno, incluso puede sacarle una que otra risa. Sin embargo, para calificar los informes si es bastante estricto, quitó puntos por cosas insignificantes en la exposición y además los quices fueron sorpresa. Pero es pasable, por si le toca matricular con él.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-07-26T00:00:00+00:00'::TIMESTAMPTZ, '98e588c5c8762ae5279c9eab5a0d50485cfc0d1766361cea48c2ba937998607b'::TEXT, ARRAY[607]::BIGINT[]),
    (198::BIGINT, 'Es muy buena persona y buen profesor, pero califica demasiado duro, recomendadísimoo para aprender y tener buenas bases, pero es probable quedarse'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2025-07-14T00:00:00+00:00'::TIMESTAMPTZ, '107b1146a0f4d6887d4f8a1fbad9640e23e249def4afa52dc5d15dbe371548e6'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profe es bastante calidad de persona pero algunas instrucciones no quedan claras y califica duro. Para la exposición final se dejó un instructivo bastante deficiente y luego en la exposición sacó rubros y cosas que no decía en el instructivo de cátedra. Pero el profe tampoco jode,'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a321e0b3223288c4f6ead24151a31b35e0b8766c1d578cfd50d015317e29e226'::TEXT, ARRAY[607]::BIGINT[]),
    (198::BIGINT, 'Como persona es muy bueno, tambien sus clases son muy productivas y uno aprende bastante. El unico detalle es que califica muy duro y los quizces soy muy complicados. Se los recomiendo si son buenos en fisica o es la segunda vez que cursan esta materia.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3fe98497d8ebd2e8aeaf60d5983f345c935b6a7c61afc5da03641671412e245a'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profe como persona demasiado buena nota, pero cree que uno nació siendo Newton y que la única materia que matriculé es la de él. Si puede escape, pero si quiere un reto de verdad y quedar con buenas bases de Física para los siguientes cursos di mandese'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Muchos exámenes']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'a9942a55caa8453976e78448bf628dcd5fc2b14bf7e620a03f519c2f773245b1'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'bde8b328f32ea03205c8912739f70f7c4c3883ec43690d00ce165476edf49fe2'::TEXT, ARRAY[607]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'b9081387871115b3e967f86eec780bd2a5dac611ee9ac4e2d0d1900fef0e43ce'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profe explica bastante bien y es muy apasionado. Es muy estricto con las reglas que pone pero son muy sencillas de cumplir, parece menos amable de lo que es, si usted muestra interés en clase está dispuesto a ayudarle. Cancela muchas clases entonces hay que ponerse al día por aparte.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '76c3e74c040abce8a5aa76d5155c9c4713a554ef0a85d260dcc3c17e947d7101'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Si le cuesta la física no creo que sea la mejor opción porque explica de más. Anula trabajos por el más mínimo error. Es buena gente y los quices los hace similares a los libros de práctica. Deja algunos quices en pareja.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd9570cd2f77ac156e7a25a85f3ad2c6f72627ef82f1f0a671ec169453341bc31'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'No matricule con él, es malísimo, el hace los quices para que usted se quede, no da fórmulas y quita los quices antes de tiempo si alguien termina primero, y aunque como persona no es malo, como profe sí, cancela demasiadas clases y le toca ser autodidacta y si eso no es lo suyo, se quedará'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Clases largas']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '6c10a58dfc8ab991f02b0b2ea58cd7bc357e8f2eee806176267d70d677bf4cf5'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Muy buen profesor, realmente se preocupa por hacer entender al estudiante la materia, califica duro y anula trabajos de manera increíble pero se le entiende súper bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'bf490424a64d59877c4e719c07edaa822dd23ae0bc13f7e1e49a2b9b5d303a52'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Si es la primera vez que lleva el curso, no lo recomiendo, explica de forma muy general. Si está repitiendo el curso, todo bien. Si no, no lo haga. Pasa cancelando las clases (como 4 veces)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-02-24T00:00:00+00:00'::TIMESTAMPTZ, 'f9e1b784a9dc63bf623d2856443b2846c6ef546cc2ab9ab1b07c65292afdfdc9'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Me pareció muy buen profesor, si ve que al estudiante le interesa el curso y que se esfuerza está dispuesto a ayudarle. En si el curso es difícil pero el explica la materia bastante acorde con el nivel. Lo único en contra que tiene es que cancela muchas clases sin embargo igual iba con la materia'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '14de0ecf00e527c3911090af1985b62f020ff013ce14e1cb10a7d09151ddbf2d'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Califica demasiado duro y como quiera, no debería tener una nota tan alta. Falta mucho a clases, enseña cosas que no son necesarias para el curso de forma muy confusa y pierde mucho tiempo hablando de otros temas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'fb96069abbb6e602716f4b5cbbc24549e7576009147080af6d867bb73785cbda'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Lo llevé en verano y ciertamente me parece un excelente profesor que se nota que le gusta lo que hace, y se interesa porque sus estudiantes comprendan la física. Eso sí, no es un profesor que esperes que te regale nada, la calificación que obtienes es la que mereces.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-11-03T00:00:00+00:00'::TIMESTAMPTZ, '0a24faa1604a193ee70c0e6f44354b01050d0cec28b906ea5f9b34d1865ecf74'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'c6f642a15839f97b9aee91369970833fab5eaf29cfed126c4cd40aec0e9535cb'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Es de los mejores profes que he tenido . Hace que uno entienda todo y que le guste la materia, es necesario hacer todos los ejercicios que envía como práctica porque en clases no se puede abarcar todo, participe y haga preguntas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3bc90d70195b2021525c1e50875ab6387f13443a20a1afe44e21046707994bed'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'En comparación a lo que me han contado de los otros profes de Física II, este profesor es SUPREMO. Le importa MUCHO que el estudiante comprenda, vaya a consulta, él le ayuda. En este curso usted aplica las integrales y derivadas como operaciones básicas (sumar, restar, ... ) de toda la vida.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a2ab0d6903b48e448993cae56caa9da90f90037081e0fe0cecc95f1e661270e1'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'El peor profesor que del Tec, no sé como tiene calificacion tan alta, el mae no explica, cancela clases todo el semestre, y deja clases asincronicas que no sirven para nada, al compa le enorgullece quedar a los estudiantes, disfruta con la frustacion de los estudiantes, califica rudo, es delicado'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cecbd0552cfc6ad47bc6e1495e042f5052ebb732d5624efc44ef83c7ff37d866'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es el peor profesor que van a tener en toda su vida, el mae no ayuda en nada, evalúa durísimo, le importa una mierda la evaluación justa, baja a criterio de él, se la pasa cancelando clases todo el semestre, haciendo que uno termine estudiando por si solo, realmente no lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, '0946a3b50a65f7856aeb269d5254ba1544157d036e5d285188ad7df45e054966'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Da muchas clases asincronicas en semanas pre examen. Los ejemplos que explica en clases no son importantes o son muy basicos con respecto a los que salen en el examen'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'fcac6d76dfbaea85ec8877d1263ccb090f7a39abd6eb94139e6687264c9f331c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es un profe muy complicado la verdad no recomiendo llevar con el básicamente es como ser autodidacta'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2023-05-05T00:00:00+00:00'::TIMESTAMPTZ, '2da41caeb8df22b2394126f0467a5516274c11458352b69a040885a5d975035e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profesor es excelente, su claridad es ejemplar. Accesible y dispuesto a ayudar. Su punto malo es que califica DURISIMO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-11T00:00:00+00:00'::TIMESTAMPTZ, '175102e78c4d7c3c52877c19ad323283af223b06bea4e9ec16deceafb20b8ab3'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Es un excelente profesor! Sabe explicar y se preocupa por que los estudiantes aprendan. Está siempre atento a resolver dudas y las atiende de la mejor manera. Las clases son excelentes!! Mi recomendación, para sacarle el mejor provecho al curso, es llevar al día la materia y hacer preguntas :) 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b9705e73ee0635adf827705df5f1bad67797a4dde4def3d2c881ce5abec82608'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Si te interesa aprender física, lleva con él. Sino, va a ser la peor experiencia que tendras en tu vida. Muchas tareas, muy dificil. Explica poco pero lo poco que explica lo hace muy bien. Hace muy poca práctica y es muy extricto. Es dificil pasar con él a menos que lleve solo 2 materias'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'b31057f3fa83ce617ee6762cbe3bf21ccf98b478dc8d54442be6b6895791f02f'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Tamo arriba como el challenger Pd: una G2 espectacular'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2022-08-10T00:00:00+00:00'::TIMESTAMPTZ, '03d20f6d23c495f54fd97b21e47b12dff57642c16ff3bcac1b5f7d2bbbc7c3b1'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Explica raro, a veces se sale del tema. No calificatna rudo. Si le pide ayuda él saca tiempo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '005e0f7b6b06472ff86860511e275234f426f360a55449fba292bf199b5f8818'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El curso por si solo es complicado, el profe explica muy bien, si uno estudia lo ayuda bastante, a veces cuesta estar al día, pero se necesita mucha practica, a lo ultimo sale de vacaciones antes, el profe sabe bastante.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '9e7cc77bbced7db29170b6a202c2640bcaed7b00724bc4692cf47d3e6a9b81d2'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'En la clase si hay que ser participativo, responde relativamente rapido y generalmente esta para ayudar, califica un poco dificil'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '39187e600915c20cfec8b2096f56b685659193d5611fec298d58d7f4b6a481c0'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Sinceramente no entiendo por qué este profesor tiene tan buena calificación, llevé con el por eso y fue el peor error, explica super raro, no hace ejercicios para comprender el tema y si usted tienen dudas no lo va a ayudar, solo lo trata mal a uno. Quita puntos por todo, fatal'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a85a0ce7194278f53ed7ece8915dbc6309ad18811ef2032ec54b753163c75155'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'No ayuda en lo absoluto y dura demasiado calificando'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, '2ee4e803dac042848f30c631e3728e37d6f768196bcf96479465f00089485392'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'El profe es bastante bueno, explica muy bien. Si uno no entiende vuelve a explicar sin ningún problema. En la clase si hay que ser participativo y se aprende bastante'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd3b342dc80e915a169292af6f24d7e0f6299a036cb9cbf2091cefbcb44685e24'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Este profe ufff, otro nivel al mae se le nota que le gusta lo que hace, explica super bien y si usted no entiende se lo explica, el mae siempre pide que participen, yo lo lleve virtual pero presencial que dios los acompañe porque física 2 es demasiado pesado en virtual, ahora en presencial :c'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'db0cdb04ff6a826ac82b948cac767b451be6028beb8c740c67cf662368de62e8'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'CALIDAD de profesor!! Tiene un verdadero talento de enseñar la materia; explica muy claro y deja huella. Las clases son completas y amenas- se aprende bastante y le preparan enormemente para las evaluaciones. Siempre está dispuesto a atender dudas. 100% recomendado- aprendizaje garantizado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-01-04T00:00:00+00:00'::TIMESTAMPTZ, '4acdfc02710e9f9eb01d4a18e2c8ff911f0e427a50329fb3cd7aca9e7dfb496a'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Virtual. Sus clases no son aburridas sin embargo son tediosas de vez en cuando. Es necesario poner de parte de uno para sacar buena nota, él explica bien la materia pero la práctica es muy necesaria para una buena nota. El curso en sí no es muy dificil y definitivamente recomiendo a este profesor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '9b773fa5bdbfe3831da6b8f3d27e07560fc7d7bea639dca691235e34e65d480c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Sinceramente, no me gustó como trabaja Pineda. Explica mucha teoría pero solo hace 1-2 ejercicios de los más fáciles y da el tema por visto, se enoja si el estudiante no hace "50 ejercicios del tema". Hay que ser demasiado autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '927c2b3c1b86047b2434ba323f1f8713ea6db553a2cc2c5bc9357fabad6f1839'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es un profesor excelente, ayuda mucho cuando se le hacen consultas, hace la clase muy agradable y manejable a pesar de la dificultad de los temas, muy recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '0040e50a2ab87159961d30d53c54087827010833927f9db886b9dc77ef9c15e5'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Le gusta que el estudiante participe, no explica muy claro pero a punta d ejemplos uno le entiendo y con los videos de la cátedra. Hay que ir al día por los quizzes y las tareas son muy largas, lo más fácil son los proyectos y califica muy suave. A veces no hay clase y avisa hasta 2 hrs después.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '45f606ca23cc50df27c64d3943425d955f041d01aee1f40b250f53ff7efa1b3e'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'super bueno explicando y atentiendo dudas. Sin embargo virtualemente sentí desmotivación por parte de él. Se sabe que califica rudo jajaj'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '124dea88effe99a2fa44efef405aaec4d9c5619d55cec6cab25b80fae33a6b3f'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, '8dc0aaf51641f852740f91b2fc2b55bc7421d0134e1116eee07a6091b4674bbc'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Realmente el curso (Virtual) es fácil, sin embargo, el profe se ausenta muchas clases.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3110b0a1992e5c53bc100476872cc73c2593c648757c7f106f4938090b724fc2'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'b67056614e1bb2ff108ff7fd197aeed430db6d0e8b3acba38c6548db523fa369'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'El curso virtualmente no es complicado , no hay exámenes y los quices tenían una dificultad bastante decente. El prof trata de explicar lo mejor, sin embargo en muchas ocasiones no da las clases.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-14T00:00:00+00:00'::TIMESTAMPTZ, '2c7e2cdd056461ad76a2d2e2b11c9705baf1ba80baff109d6a2fd49d493c7f30'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Respetado por los estudiantes']::TEXT[], '2021-05-13T00:00:00+00:00'::TIMESTAMPTZ, '1a1e2b7505dea5d8ab0aeb41de897e4954bf36cfad85fd23d0c8a4670b9bdfe1'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2021-04-26T00:00:00+00:00'::TIMESTAMPTZ, '579ef54f074f7a8d6214a44cb1c8c718f5e773c2c4a61f668fce4c9fc47acb5b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-04-26T00:00:00+00:00'::TIMESTAMPTZ, '456d5220f0c7419c3513273adc18c3fb63a545096410575fbd92b973a811ad91'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-04-26T00:00:00+00:00'::TIMESTAMPTZ, '4beb85215b7146e802155fe64103408559f529ba89652855e186efb55dda5f9b'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Hay que ser autodidacta ya que lo que explica es muy general, no explica casi ejercicios. Hay que leerse el libro, ayudarse con tutorías y videos de la catedra.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '33cde817808f231bd47ed53a0c0ea7fa1ed4053950ab193b122c41f5a7d328a1'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'A menos que usted sea autodidacta no le recomiendo matricular con él, en especial en modalidad virtual. Durante el semestre cancelo casi la mitad de las clases y lo que explicaba era muy general. Dar la clase no era de entre sus prioridades'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '869da405146def260354bce304aa1ff4d0fd4b9b6c8f55872225933c7da35ede'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Si ud es una mujer, NO matricule con él. Es un acosador, abusó del “poder” como profesor para obtener mi teléfono y me escribía mensajes obscenos e insinuosos. Me dijo que le gustaba mi escote y que me sentara más adelante en la clase. Conozco al menos 2 casos más de mujeres acosadas por él.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'La participación importa']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '7e53462ab65ebb0e372aea74f56933a74ca0fb844910329d95eb36b2c07cf043'::TEXT, ARRAY[3258]::BIGINT[]),
    (198::BIGINT, 'Explica muy bien, hace muchos ejercicios y es muy organizado. Física 2 es con PineDios'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '4890721a9f4749a8317d38a2875655174453f898a84f6d452d73757304c948ad'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'En virtual, solo hay que cumplir todo lo que mande la cátedra. Él como profe no ayuda mucho, el horario de clases es solo para consultas que él medio explica. Fácil de pasar.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'a59f67675de3932d02e9bb951fb2b29e490d868cc38ed2a62e74d21cf9ec7f57'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, '(Virtual) El curso se impartió super diferente, cada semana la cátedra subía material para estudiar asincronicamente (ejercicios resueltos, vídeos, explicaciones y ejercicios recomendados para estudiar), dejan tareas, quices (Gaap), casos, y actividades de seguimiento, cada semana alguna cosa. FACIL'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'b0ad799a728642a8ff79b8982a3fd560380d19e1a73f60bd00e929f984be6db9'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '607f1a7981632c7fddb9e76784c474aecf042a87e1dc4c719f0ff09324579cd3'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, '2af551651a0dad896f24c7311aa126007449020c688cf40843d794766e8a997e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es pésimo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-12T00:00:00+00:00'::TIMESTAMPTZ, '23ddb4b6e9960ac066eb0c387fe48f9fa0bcf8cc9a936d013d316b1b7694d637'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '30540e8ccf0ff73273c86e81d74510c7f6a5f0e6639eb6e858da769a4e76ef14'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2020-01-27T00:00:00+00:00'::TIMESTAMPTZ, '04a68719e48e76defc5dc430ec1bd1d72d10582d9d2cb1d22df3e2c65005db7c'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Como profesor es un crack, sabe demasiado y cuando explica la materia usted de verdad entiende de dónde vienen las cosas. Deja muchas tareillas sin gracia, y si no sigue los lineamientos para tareas le pone 0 (pero no es nada difícil seguirlos). Ah, y si es mujer no se le acerque mucho.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2020-01-08T00:00:00+00:00'::TIMESTAMPTZ, '47214a898c0487d316bebf6fc8510680a290ec6b996745c7884d167e6a40012e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, '018f4b3a1ccc6c718e67a71165462cdc8beee50f7167f69871e6fc32fdeca72b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Muchas tareas y evaluaciones sin sentido, que no ayudan en el entendimiento de la materia. Se inventó su propio método de evaluación que si no se sigue, puede poner 0 en cualquier asignación. A veces una clase sólo para explicar de dónde viene una fórmula. Muy mal. Para nada recomendado'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '007a5ff44717aaf9e5ff27f31ae398d887bad2f6c8750d54dbce9ad4fb2d87d6'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Considero que explica bien, pero tiende a usar las clases para demostrar formulas y explicar cosas triviales sin hacer muchos ejemplos. El problema es que su forma de evaluar no tiene propósito y es más como un juego para ver a cuantos queda. además de que hay varias acusaciones de acoso.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '9dc2e141ab388f6b9f8850efaa6a9ae48521218237cda64acec78d20b2fb471c'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Lo peor de la escuela de física, no importa cuanto tiempo haya gastado de su vida para entregar una tarea completa si no sigue unas absurdas instrucciones le pone cero. Las clases son para ir a firmar la lista porque tampoco sabe dar ejemplos de ejercicios en la pizarra.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'dc9541f1f9a3049206dc110990b1fc31485b7c33502b0b159f8e3052c43b61d7'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Pésimo. Le interesa más que usted siga las reglas de él (escribir con lapicero, usar hojas blancas, no tachar) a que usted entienda la materia de física. Pone 0 absolutamente por todo. Hace sólo demostraciones y nada de ejemplos de examen, se salta materia y luego se quita el tiro.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'c430f5ad17aafad12e060a55d08e4a0352f11d4a84a9a5e12be3ad1aae0f176c'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'No meta con este profe, pone ceros en quices y tareas por cualquier cosa , califica muy duro , si mete con él preparese para estudiar solo, la mitad de la materia es que entra en el examen la deja para la casa.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2019-10-23T00:00:00+00:00'::TIMESTAMPTZ, '25556223e7edf556e92391647d4578ba964cbf120495cdd9e7ebf5640adf8eea'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'El profe es excelente. Explica super bien dando ejemplos muy claros y precisos. Tiene una lista de reglas que cada estudiante debe cumplir siempre, en caso de no hacerlo espere un 0 en cualquier evaluación. Prepárese para pasar a la pizarra varias veces en todas las clases. Pero es muy buen profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2019-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'c9b82c9527dc464fb37ef26c1c0b05e84ac769ea1628bfe4a10d772f4162dda4'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica bastante bien y menciona datos de teoría relativamente importantes, los ejemplos que da en clase son básicos por lo que hay que estudiar bastante. Compensa lo estricto en lineamientos de formato para tareas con quices accesibles.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '766a59090a366b11054e1d3f3bb7e0e70ef6519c06bea49dff4d378d50f199f3'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Excelente lo recomiendo muchisimo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b34f981c384ae89780fd4d719cb066127f12f5b9abb26373cdd69de1ca6ec6cb'::TEXT, ARRAY[3021]::BIGINT[]),
    (198::BIGINT, '5mentarios'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Inspirador']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'efffb3b98292ba3fc94aae1babd11573b887b7dc89edb1e2d9cf9a845f04dc21'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1b56b9b27707ac61926fe7a511f6b8f224899937afc83a365dc25eb0c6299093'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Hay casi me quedo'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Respetado por los estudiantes']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2c275c207275438bf880779235dc6e42bae8a1f18cb1d05859bc3aa8bc194677'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3e89bd942d9fd215a09c694c1aeca1fa7aa1a42ecee7c96163f4aa88ff0edd7c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica muy bien pero es muy exigente con las calificaciones de las tareas, para las tareas pide un formato muy especifico y si no lo sigue es cero, si le pone al curso aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '85fb2f9a8b5e01326783d670caa81ccec04b89344e5eac1f5aee172fa75051fc'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'No explica tan mal pero jode muchos con las tareas y quicez, deja tareas todas semanas que no sirven para los examenes, no se puede usar lapiz ni hojas rayadas, matricule con otro mejor'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2019-05-31T00:00:00+00:00'::TIMESTAMPTZ, '2ab8938df55f65b51af8124147e7da61b1b5cb5a22792c2b089f3fc445a0e040'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor, se dedica a que el estudiante aprenda, exigente con las evaluaciones, pero mientras usted se apegue a su manera de evaluar desde el inicio va a ser un éxito, le gusta que los estudiantes generen curiosidad en las clases, la verdad súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '47b7e3809949e6aa91edbd905f2cd44808a75c3b09dc0f8a2470387903e56df4'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Un profe que sabe mucho, pero hay que acostumbrarse a su forma de evaluar y a su forma de ser. Obliga a los estudiantes a participar y los humilla (levemente) por no saber.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-05-09T00:00:00+00:00'::TIMESTAMPTZ, '8bd4b0867c872a39c799acc288f1e5c314041ffb9f343a52e46e8bda921a9baf'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Uno de los mejores profesores que he tenido. Es justo calificando, sí, pero él solo espera de usted interés y asistencia a sus clases, así que no le va a calificar nada que él no haya explicado. Tan buen profe que me duele no poder llevar Física 2 con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'c69efcd3f115c37eec5798d6e37fe83e3ad9520d7ce1d43e73cd17c4971a5caf'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Sigo sin entender por qué lo califican de buena manera. ES egocéntrico, juega de vivo y sarcástico. Le gusta humillar a los estudiantes. Hace como 3 quices y los ejemplos en la clase son muy pocos.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '7f80ca6fe17effcde7b514d9cd39fdef5da0195a0ba8d736fa0ae9c8e3285c92'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Buen profe, explica un poco de mas materia que no es necesaria para el curso.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '31bee010e2d000d8749e3e59b321d294ddce58bf9f7832b7eec5ed92d4013ddf'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El mejor profesor que he tenido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '268bf451ef33f6e4e4c17b2a145dc02a839bfe6f034986fde505a0591d262152'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Muy buen profesor, ordena y explica sus lecciones con claridad. Es muy estricto al calificar los quices, tareas y trabajos en clases, pero al final siempre da algunos puntos extra. NO FALTES A NINGUNA CLASE y pasarás el curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '20df706d37d09f07b1c287e6462525fee060e28a94b785bcd83d1e7ebd7bf01b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica bastante bien, es agradable, deja varias tareas y quices pero todos los avisa desde la primera semana de clases. Hace la clase divertida y aprecia mucho la participación. Es bastante estricto con sus reglas, pero no son difíciles de seguir.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ff2d628da710c4eea6922e479ecd94844fce3350ce5fef9873136374a58d4e9c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Honestamente el peor profesor de la escuela de física, sarcástico, grosero, arrogante y se cree el mejor del tec. Pésima experiencia!'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '95ddd75609318a73dbaf9c41d36021d25a7402148edc43a104d950679aea4c42'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Muy buen profe! califica lo justo. Es estricto con sus reglas pero nada que no se pueda cumplir.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, '48bb23a389d217b860216cb6232edee91979ba59afd5894da97d5d5d4e6bdef9'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Lo único malo es que es muy estricto para calificar tareas y exámenes pero se aprende bastante con él, la clase es muy amena. Valora mucho la participación y llevar la materia al día. No apto para florecitas sensibles.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'La participación importa']::TEXT[], '2018-11-15T00:00:00+00:00'::TIMESTAMPTZ, '87be001e223dca8c31719537f80919417536b3326ba92bbea66b7b1477536edc'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor, hay que acostumbrarse a sus formas de evaluación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'a31bf90d29bf2b5abbdcafbe54ea2cc11283d73cdc16b2596b1b97b7ac11514f'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2018-10-18T00:00:00+00:00'::TIMESTAMPTZ, 'cddba6a5c485e9f819286058409a0f034d53efeffdc4c7a0c2a57b5fe4d297d6'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Pocos ejemplos en clase. En ocasiones pregunta con frecuencia y si uno no sabe la respuesta, intenta humillarlo, si responde bien, le va a caer bien desde ese momento. Muy exigente con dibujos y otros detalles. Es buen profesor, pero si uno no entiende, ni modo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c10f0f7990b3eeb312858bf81a54e31d8568414212d929d501617b3c3bcf6221'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Hace varias evaluaciones durante el semestre. Las entrega hasta el final y todas vienen con un 100 (excepto quices). No permite utilizar lápiz en los exámenes. Falta a una buena parte de las lecciones. Da una clase muy interesante y entretenida la mayoría de veces. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '06c463d6ee74bd79f66103b14be32efa4578b7fbc4713ff236c46d9268900933'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '44778da05b8c6fe410297db44e4059941f575fc03165921631edd927371eaa5a'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Da un ejemplo por tema o no hace ejemplos, los quices son sorpresa y son pocos, deja mucha tarea y no las devuelve hasta el final del curso, dura un siglo revisando examenes y califica duro. a veces no llega a dar clases y no avisa'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '17a820438b128880f944995e1fcbd18a6cba44a546a468d92db6b600a09ade11'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Da la materia con claridad, pero hace muy pocos ejercicios, califica un poco duro y es irresponsable ya que devuelve todo hasta el ultimo día; si usted va a consulta le puede ayudar bastante.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '00b66befa803100c70826f8fd5c85233b665fadbd533b13f0ffb091cbf575826'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'El profe sabe mucho y retá a los estudiantes a pasar. Es irresponsable porque falta a clases sin avisar y nunca devuelve tareas. Pero es bueno explicando y cae muy bien. Vale la pena!'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b3052b06bbd606befa29ff20669d870618bd97fe5a45475311a7c336e98799e6'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'El curso es difícil. Uno aprende mucho más que con otros profes. Califica duro pero enseña mucho más que otros entonces uno sale mejor en los exámenes a pesar de que califique duro. Si quiere pasar haga TODA la tarea de cátedra antes de los exámenes y no falte a clases, valen la pena cada clase.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '034c81b3124360e6ff5f9968295b7a8eed6bfa47afe0c0ab9585c08afae9c209'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profe es buena gente, las clases son interesantes, explica bien la materia y aclara dudas. Califica bien, no es binario. Es estricto con el formato de entrega de trabajos, deja muchas tareas, pocos quices. Es buena opción, eso si el curso es difícil y hay que hacer mucha práctica en casa.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '1ae4a680ba59432c905c9a4994380b86af5940b1508a1d9aae58653d90d7c9e1'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'De lo mejor que hay en la escuela, explica bien, hace la clase interesante y entretenida. Califica justo. Lo malo es que hace pocos ejercicios en clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f8037648c0b69d1e6dc26f0795df74924bebf8d367883448cd552829892c0f8f'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'd610c997eff7d687a06f1222f1548c387b62d6893fb0e79ff2a278c067d5b7c5'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2018-05-11T00:00:00+00:00'::TIMESTAMPTZ, '56f47bbdf55fb2fadbbcbb5cab208502c6862dea1a0c51becf857a569bb3fbad'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Demasiado malo, pierde mucho tiempo y es exageradamente irresponsable. NO MATRICULE COM ÉL!!!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '799661a169f847bb4508caad60835b462496d45bc1ae394d3477529be772618b'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Muy irresponsable, llega tarde o simplemente no se digna a llegar, además que es un desorden con las tareas. Pasa hablando de cosas que nada que ver con el curso al igual que las tareas y se pierde mucho tiempo. cuando le da la gana enseñar lo hace muy bien, pero eso pasa 1 o 2 veces en el semestre.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'c488123929e972071c03cd97a616be2c542ed2e25b85bf918659f0b233c4a113'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Mal profesor. Trata de exigirle a los estudiantes y él super irresponsable. Muy desordenado con el control de las tareas y trabajos. Las tareas que deja no son relevantes para el curso. La mayoría de clases no son relacionadas con la materia de la clase, se pone a hablar cosas que nada que ver.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b4bd5ed28a4a68ea79ad230ef74b6a51654261b4aafbb43f9e468c3e86ab4f57'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Hace la clase muy interesante y es excelente explicando. Deja muchos trabajos pero califica justo en los examenes.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '6d91424784bb7c1602ff152927ff1fc3cd17667e81bedcf8149ffe28e04bba9c'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor. De los mejores que he tenido en el TEC. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'd4bce40e5aa7ef5e1cf72b30784c0358d44c1b369235e9d890e87ab9abd93466'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'excelente explicando pero no hace practica'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-18T00:00:00+00:00'::TIMESTAMPTZ, '77ae38356a50f389c9c6591b76180fe2d0bdb54cea5b6eba9c04aa6ee753b2ee'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Una basura de profesor. Falta a muchas clases sin avisar y puede llegar media hora tarde cuando se digna a asistir. Muchas tareas inútiles y hace poca practica en clase. Califica duro las preguntas teóricas. NO lo recomiendo para nada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-11-10T00:00:00+00:00'::TIMESTAMPTZ, '57220780657d8ccf5aa0d27a0fc8bcb1e6a111a8b41dd14b081144a227d4b053'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2017-09-17T00:00:00+00:00'::TIMESTAMPTZ, '86f59a8a7a6dcd5ee2422294cc9ea3999936b2a196c36f85292a1ccf32e303ad'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es un profesor de Universidad. Pide que se lleve la materia estudiada al día, no da clases aburridas, pero si se requiere un esfuerzo extra en sus clases. Un buen profesor.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'ce3760b8561b663106fa9eb0b03980584b83db8efa8850abfc9d99f38195d0b6'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'De las clases que más se disfrutan, le gusta preguntar mucho a los estudiantes y pasarlos al frente por lo que hay que estudiar antes. Con la materia es un completo crack, solo que no hace mucha práctica.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '68fdbf4d0ce972a04f8756edd271dd7e3bcef2b3e1d4278d6aae153f43c56c9a'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'no se le puede llevar la contraria. si hay alguna dificultad con integrales,derivadas o algo similar, unicamente los va a pasar al frente para humillarlos. tienede a poner ceros en los examenes por hacerlos en lapiz, sin importar si se le pidio permiso por alguna situacion especial.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1ad894041e8261cbb2297623238df8f65c61fe60fd56795cb827b4e3535c8cee'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor, se interesa por los estudiantes y trata de ayudarlos lo más que puede, es estricto en algunas cosas, hay que hacer bien las cosas, no le gustan las mediocridades, hace la clase muy amena y explica muy bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'cd75b635d67d88f2a170ec83c1c06f325549cffb745dc6f268f90d6844b0054d'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Falta demasiado a clase.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ce383d9fb6c09d3b90582b80f1e25db8eff545c1401cabef5c2e2c79a44a4d54'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Las clases uno las disfruta mucho. Se llega a aprender mucho más, no solo de los temas y la materia. Hay que estudiar regularmente estar muy claro con la materia para que le vaya bien y no lo humillen. Deja muchas tareas cortas y es estricto con la presentación. Falta mucho y es medio vago.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Inspirador']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ff67e536ba059f3d127c594411f95ad81ae9e01bb338ef11cd2c8871bb4f2064'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'PONGA LAS REFERENCIAS BIBLIOGRÁFICAS EN LAS TAREAS!!!!!!!!!!!!!! Si la tarea es del libro ponga la referencia del libro sino te pone un CERO. Enseña muy bien y se preocupa por que uno aprenda. 100% Recomendado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd87c743aa9b3c25e7fd20f6b2fce60fc11d3ae53c48facb246cbc51921b42d5c'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Deja muchísimos trabajos, súper cortos que le tomarán 15 minutos hacerlos, generalmente ejercicios del libro, NUNCA deja tareas de cátedra porque dice que la idea no es que la copien, sino que aprendan, Él se lleva por igual con hombres y mujeres, siempre y cuando no sean unos mediocres.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd5bb65b4e46cb4d9f12d0e640c3106f64a0353e29579c8857a0d6160513cc491'::TEXT, ARRAY[604, 630, 607, 631]::BIGINT[]),
    (198::BIGINT, 'No lo recomiendo, califica duro y deja muchos trabajos.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c8c5b4684563c49d88361a283a52ca46b1589fa0db0e78a9e2ea8ecc484a1d3a'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Es un IRRESPONSABLE, siempre llega tarde o no llega, dura un mundo entregando evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '4237b6deb79c20c410c0bce69e10fb90851fbb15bfd773d87854302eb0378cd3'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor. Si uno quiere aprender definitivamente hay que matricular con él. Hace las clases muy entretenidas. Le gusta que sus estudiantes participen así que hay que ir estudiado a sus clases. Se preocupa por el aprendizaje de sus alumnos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '20743a7368b18644721175a19979816b9dfd165f6249c7b4f619bab2339c443f'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Excelente profe y persona'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'a3ca95919e13a538937ec979601e9c41ffa4f15e05fdf7f73cf0442c42657754'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'd4b7a2992c17ed06ab72f632d87e7ca40eba293b20aa4dcca27ad912f1f908ec'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es buen profe la verdad, solamente que generalmente explica solo la parte teorica y demuestra formulas, por lo que no le caeria mal hacer uno que otro ejemplo, si usted es mujer fijoo le va a caer bien jaja Hace la clase amena y se toma bastante en serio la parte de las tareas, solo es de ponerle!'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'd7b3270e28e180c29082133e8d43c81fe88fbf0eb4cad9e25a371a2f1c9f8857'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Dicen que para Física I es bueno, pero para Física II es mejor meter con Segura o Nemesio antes de este "ser" al que le llaman profesor...'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '28a2f889cc732c865daa9e31eec7ef08824600c6ac64f333f4013dea6d04598d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Buen profe, recomendado. No hace muchos ejercicios por lo que hay que practicar mucho por cuenta propia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '36167dc6aac77b8cef012e75da548b60dede5fc40bc81df1b063d64a8cce9f66'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Excelente profe, muy apuntado con lo que hace, le gusta que sus estudiantes aprendan, la clase tiene un ambiente muy tranquilo y cómodo, la vdd es que si ud quiere aprender, meta clases con Pineda, super recomendado. Eso sí, no es facil, pero lo bueno cuesta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-28T00:00:00+00:00'::TIMESTAMPTZ, '97a9e563ba477f43428d459e22a7b6a207322a4695e6489aa09b7122c051e01e'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Cada clase explicó la materia con paciencia,claridad y humor, clases participativas,deja muy claros los conceptos del tema.Califica justo, desde la primer clase pone las reglas,y explica porque las pone(al final son para beneficio del estudiante),recomendado !'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'ab8a6994f85cc0a0875887bcba2b44ebc38c1448538800554004238b60e95e7f'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Deja demasiadas tareas, resúmenes , biografías, además de las tareas de cátedra. Las reglas que tiene para hacer los exámenes y trabajos, suman una presión extra al estudiante. El curso es muy difícil, faltar no es una opción. El profe explica muy bien y la clase es interesante.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '3f9d331beb290af2f98961e22dd883eba77054131fffdc0d42dd73a8e39751cd'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'EXPLICA DEMASIADO BIEN sin embargo, no da ejemplos prácticos, así que es responsabilidad de uno practicar en la casa a consciencia'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'a274a1a589501c4d8d763d240500e137cbd68e6d0bf004a8bd34013f7ce5cf5b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica muy bien, se nota que le gusta la materia y se interesa en el aprendizaje del estudiante. Las clases son entretenidas. El problema es como califica y la cantidad de trabajos que deja. Hay que dedicarse al curso al 100%'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-07T00:00:00+00:00'::TIMESTAMPTZ, '20477d7bbce45662e6012d47cb50a8eedff139b11ce35d80bb816672ab82ecb8'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'el profe sabe demasiadoo, es un crack. pero su manera de dar la clase no es la mejor. no hace practica, pura teoria con ejemplos sencillos. buen humor'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-03T00:00:00+00:00'::TIMESTAMPTZ, '12f3fa0d9daead9e75f51e12e751c04f1f8fdac8eec76fe5789cee4fbac74fea'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Las clases son muy entretenidas y explica muy bien, atiende dudas, él le ayuda siempre y cuando usted vaya a consulta y demuestre su interés en pasar el curso, las tares son útiles para reforzar conceptos que no se tenían claros'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '1fd16b66598b1a50f2708309b74a5e1913b616e41dcc5a0e3a61d6d5cc6c822b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, '¡NO lo recomiendo! El mae sabe mucho pero es demaciado rudo para calificar, deja tareas basura que no te ayudan a pasar el curso, hace pocos ejercicios y es demaciado irresponsable. Ademas no ayuda en lo absoluto.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'd12f90bdf6400e67b23fb169ff4204fecd8bfa23cf539b02a887661a7133a24b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es excelente explicando con sus ejemplos y humor, hace ejercicios basicos y recalca lo más importante. Pero no hace mucha practica'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'b31672ddcd53788b97c5e4a7e73293a8663f8bfa19e574a65f4d66fde5115112'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica muy bien, hace la clase muy interesante y divertida. Pero deja muchos trabajos y baja puntos por cualquier cosa, califica de manera justa pero tiene sus reglas.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2a7a1e9bc8b2e4ddf913517374f4d2beeb79f28e2c3fa27d610309d939b00799'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'De un grupo de inclusión de 40, solo 1 pasó y con 70. Deja un montón de trabajos basura, califica duro (en todo lo que pueda juzgar) y no le interesa que los estudiantes aprendan.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '01f78716dacf89c770fd7f56ff36efc1441c9c18530cf8ee2c7e7f64de3b4751'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Fisica I por si sola ya es dificil El profe es sumamente inteligente ,explica EXCELENTE, con detalles y todo ,incluso el sabe que tipo de cosas le sirven saber para el examen ,si lo lleva con el,APUNTE. El unico detalle es que no dejao casi no hace practica ni ejercicio'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6b9ecd6525903fe52831d872d8d14cd607453b1c61b2223d98c51e950421941d'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica muy bien, ayuda si uno tiene dudas, y lo mejor es que se toma el tiempo para revisar paso a paso loe examenes lo cual es bueno.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ebae34b5a4f75667080bcae1e756ba86887c1d20651f82c5e5dd895b72d48dbb'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Pineda es un dios a la hora de explicar. exelente como persona y como profesor. ayuda y hace preguntas para ver si uno entendio. eso si , los examenes son muy muy rudos, pero se disfruta'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2016-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'da0a9630f8b3a4bae99f58777a8d842b6a3cdecdb34cdf4df22b4eb387b9d220'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, '¿Pasé el curso? Sí. ¿Explica bien? Sí. ¿Lo recomiendo? No. El tipo nunca hace ejercicios en clase.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2016-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'b609268f3460df5542b0d747aa751bda5ca7b76a5fa8d0bcf5a3140c41241f29'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Clases muy amenas, su sarcasmo le da un humor a la clase demasiado bueno :) cumpla con los límites que el pone, lea lo que el le diga y ud tiene el curso pasado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-12T00:00:00+00:00'::TIMESTAMPTZ, '9fb04c6e6b6d932e87dcc879ac12d27311f77607758d84248aad6f42495549ce'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Es muy claro a la hora de explicar la materia, se aprende mucho con él, deja bastantes tareas, califica un poco duro pero es excelente profesor, lo único malo en mi opinión, es que es un poco irresponsable y a veces falta a las clases, pero por lo demás lo recomiendo bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-12T00:00:00+00:00'::TIMESTAMPTZ, '215e8408c33c981e4407842b1d8c67be94f8059f5365ca5cc56b0b24411d777e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor. Explica muy bien, da teoría y después se practica con ejercicios del libro. Hace preguntas a los estudiantes para ver si entiende ya que aclara que son cosas que se ocuparan para las demás fisicas. Es entretenido y existen momentos graciosos con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c0602ba448a807d454ad5bb6b13777032ea4d88e66a03206276f08c6774b04a9'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es buen profe. Ve lo necesario en clase y obliga al estudiante a buscar por sí mismo mediante tareas y otras asignaciones que son muy frecuentes durante el curso, lo cual ayuda a mantenerse en practica aunque uno no quiera. La clase no es aburrida. Pregunta mucho en clases a cualquiera.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8d6b9b771b5045f2a56eb8643e051c605d9bbc4e5f4d11afdc9676350e6e25b1'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '88fb656f8119d07558ce90f4cb2e158219f349727cc32d9689cc509a3aa6a143'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Esperaba más de él como profesor, pero como persona es excelente. Y lo recomiendo sólo si usted es autodictada.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f37cc65f56840271241214a8c7011ae58bb514d0b6d5b6b9fa033d36dc450296'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Las clases son un chuzo, explica bien, pero uno tiene que poner mucho de su parte como con cualquier otro Profe de física, pero es rudo y hay que ser muy ordenado y seguir ciertas reglas que explica en la primera clase. También las clases son muy participativas, por si se es timid@ no lo meta con el'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '0bb0031b63fbb2c7c3e2cdb5373f01f3fa893871eeb9e4f4d453ee10fb004252'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '8f40fbed041f551d60d5601b718420a8c96140e7ae52b5e47122b37ae710386a'::TEXT, ARRAY[604, 630, 607, 631]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e483c5b1676b89af50f1601a13ead1e1cb8765205f7a62a5f64801abfba8a26a'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0b4931578ad3af33adfee7dbef7febbb88c8da586acddeb00fd187f76600a30b'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El profesor es claro, sin embargo todo es por cuenta de uno, él no hace muchos ejercicios ni prepara muy bien para los exámenes, pero si uno tiene una duda si la resuelve sin embargo es exigente y califica duro'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '61f0f2b981810ac8618ae4b3596d1e562ccd79735aa9327b04565f82ec860f15'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-04-07T00:00:00+00:00'::TIMESTAMPTZ, 'e892e9740807d590197cabd2f4d4787ee8eb6d429ea2e64c741ff1de7b6418da'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'b270a81fa49461795a1cd264421114e4c0390b883a55a473a898b5e87313ee5e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El es una teja como persona y profesor. Tiene sus extravagancias como que en el examen todo debe ser a lapicero, nada del otro mundo en realidad. Las clases son muy entretenidas y valora a los estudiantes más esforzados. Un profesor muy recomendable si ud quiere aprender y pasarla bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'La participación importa']::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'ded496a26e933eb14a21505750f15f86412e7860eebadbfc5ec46b014df54580'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'El mejor profesor de física, explica súper bien y las clases son entretenidas. Tiene ciertas reglas para quices y exámenes, pero nada del otro mundo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-11T00:00:00+00:00'::TIMESTAMPTZ, '6a45858953a84443a6c5243bad3d1ed5161448023f959293fafee55248487347'::TEXT, ARRAY[630]::BIGINT[]),
    (198::BIGINT, 'Pineda es Pineda, es un crack!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2015-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'ef80509c536ff6471b1fc347cae38cf6187d126da275b3192e27b1c33d9cd599'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica muy bien,hace que uno ponga atención, es muy muy dolor con todo si uno no hace las cosas como el quiere todo esta malo, agrega más presión al examen de la que deberia haber, deja muchas tareas lo cual es bueno pero tambien se hacen varios quices, y nunca los entrega, califica muy duro'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '3733d3cc10fc7083d1d6ea4b827861a3488908c5e416375c940194aa717771e6'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e5239a58846859f6745c3ed418f9d09a9042eb4edbafbd12d89ed41e2ec5d97e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'b08005eea4b9a937273eca23dcf8d9fd700c1192303406036a7ebbea78270cce'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '040402825731e73ac5ad71aca5c32a48ed75553977a853a651ad63bdbde0dcf9'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Explica demasiado bien, hace la clase divertida y logra que uno se interese por la materia, es muy estricto pero con la calidad de profe que es y si se pone un poco de esfuerzo esto no es problema.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-26T00:00:00+00:00'::TIMESTAMPTZ, '417e9f5b87e25673e1b77d4192a49f0a1cec98597f56bbd3410dfdf0b497e6ac'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor, con él realmente se aprende del tema y se le pierde el temor a la física. Un profesor comprensivo, retador, y valora mucho el desempeño de uno en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-10T00:00:00+00:00'::TIMESTAMPTZ, '55d380dae1510f54a70d4031f202f91f5ce3dd6af34502f04e52ac3b283b9501'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'El mejor profesor de la escuela, desearía haber recibido las demás Físicas con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, '96f2623f10180d9aef3540654f134554ffcdf9211bf163ed7efa193ef36b774c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '9eb392ec806584ae41ae8c44274e7bc5596da9a27d7c25b052d646a3f412678d'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Excelente profesor!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'b5ee8842db185499361d6005a63ac979d3bb2c33da44cab73021eb3c0b6359fe'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, '¡Pineda es Pineda! Explica muy bien, califica normal, hay que ponerle bastante, es excelente en lo que hace, muy apasionado y una teja como persona.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '9658a36767bc2f06a13184281ce72ebfa37e0db52eaa88a86c679591575cbc78'::TEXT, ARRAY[604, 630, 607, 631]::BIGINT[]),
    (198::BIGINT, 'Excelente profe sólo que con él se requiere darle mucho tiempo e importancia al curso ya que deja muchas tareas y pregunta en clase. Pero con él de verdad se aprende y explica bastante y eso ayuda mucho para lograr pasar el curso. Las clases son muy divertidas!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '869422fe34008600ca71deb541f1755952d9f5adcc597858d5a183551a4301c7'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Excelente, un buen profesor tiene que ser estricto, hay que ponerle mucho, pero así se aprende'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '4085903aa4964a0349a18b9b0f38ec53882fe34df54429f2aadaaafe47bf09e1'::TEXT, ARRAY[3257]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '98157b50428a94165467c3009da9de59f9af9dc8e8ae668026ce7b5e1bc52295'::TEXT, ARRAY[922]::BIGINT[]),
    (198::BIGINT, 'Es un profe muy estricto pero eso es bueno para una materia como física, una característica importante es que pregunta mucho a los estudiantes, cosa que no a todos los estudiantes les puede gustar, pero en general trata de dejar todo en claro. Lo recomiendo bastante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'de1260862a425b115a5b39f0ffd605dc0261cc9ca6f669ac1935b76546f35422'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Buen Profe'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '660a5147ebfaee0fe7e4d6db9c79551299b7d6e6c3d346e9baacdfaed1f2f387'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b8a27851d8e3571c16e607f77d93ae5ada08a1d9c2a7e5176887038def9401eb'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es muy estricto pero si uno le pone ganas pasa, tiene algunas reglas en los exámenes pero no es nada complicado seguirlas, de los mejores profesores que he tenido en mi vida'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '31112892f17f66ce6b25c9cd0164db794bc1fe32f35666e2868ca920df759c0d'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4b80d528ca5e6ccc849a669cf4f6be6d228e087b451e618f52f934a947f47015'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Estricto. Pero se aprende bastante. Recomendado si se tiene que continuar con cursos de mecánica en la carrera.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '48d7c3887664d6680754b84f62603850e71c6a964aaa27fb2929f19b3aa29184'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es estricto MUY estricto pero es una teja el profe'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '155492a6379b9b12e3b9a7280d98bac582be952b9dfd0d6a50406171da97324f'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c1bcc5258e291722a7437b24f9c8c0b9f6a31eaced95e74f0cb7f8371741e82e'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es un profe muy exigente, se emociona explicando, a la hora de calificar trabajos es muy vago eso sí, y siendo sincera cuesta mucho pasar con el, normalmente lo logra como un 30% de la clase, también es un teja de profe.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f568f506c175d87b06f8bf778b0728ed32be88ea34cc409f4155b43c1cd9620c'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Es demasiado exigente, pero esa exigencia obliga a llevar la materia al día y a cuestionarse acerca de la veracidad de lo que se estudia. Es excelente. Deja muchas tareas y pregunta mucho en clase.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '502ba943996b1d3b40fcaff6796b807345e6b26f9317951fd0e17cf2fd7ec38f'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'califica duro y es muy exigente pero es de los mejores profesores que he tenido'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a53e218bc8e7432efa8004db329d4bcf451d022755a0529f6eca0c8f612fb5b9'::TEXT, ARRAY[604]::BIGINT[]),
    (198::BIGINT, 'Sabe explicar muy bien, hace que uno se cuestione y quiera saber más, es una teja de persona'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c8d33f4c5f4d3dc2947bc256af2eef234b2e187af9026a1428feb33b4dd65bfb'::TEXT, ARRAY[604, 630, 607, 631]::BIGINT[]),
    (198::BIGINT, 'El mae tiene sus cosas, pero si es un buen profe'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1b2ac9140e3b6f03613f362baed42deb6822019949706285226279ed529000a9'::TEXT, ARRAY[607]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5904abb5d83d34b38a29f8d81e65c549be3226ce0dfff7b463965eb5e2f085c2'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Deja muchas tareas y eso ayuda un montón. Explica ejercicios de la complejidad del examen. Eso sí, hay que llevar la materia al día, pero es muy bueno.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '917998e502e9159a813a95366a392db8b95c8df3817edb9ebfeb9da4980eabfe'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '9d2ff49899c0454458fc0f8c7441210fdace9ff39d257e7816a6e4af36e65034'::TEXT, ARRAY[630, 604]::BIGINT[]),
    (198::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '63f89035d063cdf85d0adb10d785954de6795dc54a90220bf18dff2ab6e38b24'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
